actions.new:
        rows = cur.fetchall() or []
        for r in rows:
            r["sistema_origen"] = "SOFTRESTAURANT"
        return _reconciliar_soft_descuentos_y_ajustes(rows)
    finally:
        conn.close()


SOFT_AJUSTE_DESCUENTO_GLOBAL = "__ISCAM_AJUSTE_DESCUENTO_GLOBAL__"
SOFT_AJUSTE_CORTESIA = "__ISCAM_AJUSTE_CORTESIA__"


def _soft_adjustment_row(template: Dict[str, Any], codigo: str, nombre: str, importe: Decimal) -> Dict[str, Any]:
    row = dict(template)
    row["producto_codigo_fuente"] = codigo
    row["producto_nombre"] = nombre
    row["cantidad"] = Decimal("0")
    row["precio_unitario"] = Decimal("0")
    row["importe_bruto"] = Decimal("0")
    row["descuento_linea"] = importe
    row["descuento_linea_pct_min"] = Decimal("0")
    row["descuento_linea_pct_max"] = Decimal("0")
    row["importe_neto"] = -importe
    return row


def _reconciliar_soft_descuentos_y_ajustes(src_rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Conserva productos reales y representa ajustes del cheque por separado.

    Nunca modifica el importe de un producto para forzar el total del encabezado.
    El descuento de producto se calcula desde cheqdet.descuento como porcentaje,
    coherente con el contrato SoftRestaurant. Los ajustes globales se agregan como
    conceptos separados. Si queda una diferencia desconocida, falla cerrado.
    """
    grouped: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    for raw in src_rows:
        row = dict(raw)
        key = _s(row.get("id_transaccion"))
        if not key:
            raise RuntimeError("SoftRestaurant: fila sin id_transaccion")
        grouped[key].append(row)

    out: List[Dict[str, Any]] = []
    for ticket_key, items in grouped.items():
        header_totals = {_d(r.get("importe_neto_ticket")) for r in items}
        total_discounts = {_d(r.get("descuento_total_ticket")) for r in items}
        courtesy_totals = {_d(r.get("cortesia_ticket")) for r in items}
        if len(header_totals) != 1 or len(total_discounts) != 1 or len(courtesy_totals) != 1:
            raise RuntimeError(f"SoftRestaurant: encabezado inconsistente en ticket {ticket_key}")

        for row in items:
            pct_min = _d(row.get("descuento_linea_pct_min"))
            pct_max = _d(row.get("descuento_linea_pct_max"))
            if pct_min < 0 or pct_max > 100:
                raise RuntimeError(f"SoftRestaurant: descuento de linea fuera de 0..100 en ticket {ticket_key}")

        header_total = next(iter(header_totals))
        total_discount = next(iter(total_discounts))
        courtesy_total = next(iter(courtesy_totals))
        line_discount = sum((_d(r.get("descuento_linea")) for r in items), Decimal("0"))
        product_net = sum((_d(r.get("importe_neto")) for r in items), Decimal("0"))

        if total_discount + TOLERANCIA_VENTAS < line_discount:
            raise RuntimeError(
                f"SoftRestaurant: descuento de lineas excede totaldescuentos en ticket {ticket_key}; "
                f"lineas={line_discount}; totaldescuentos={total_discount}"
            )

        global_discount = total_discount - line_discount
        if abs(global_discount) <= TOLERANCIA_VENTAS:
            global_discount = Decimal("0")
        if global_discount < 0:
            raise RuntimeError(f"SoftRestaurant: descuento global negativo en ticket {ticket_key}")
        if courtesy_total < 0:
            raise RuntimeError(f"SoftRestaurant: cortesia negativa en ticket {ticket_key}")

        reconciled = product_net - global_discount - courtesy_total
        delta = header_total - reconciled
        if abs(delta) > TOLERANCIA_VENTAS:
            raise RuntimeError(
                f"SoftRestaurant: diferencia no explicada en ticket {ticket_key}; "
                f"productos_neto={product_net}; descuento_global={global_discount}; "
                f"cortesias={courtesy_total}; encabezado={header_total}; delta={delta}"
            )

        out.extend(items)
        template = items[0]
        if global_discount > 0:
            out.append(_soft_adjustment_row(
                template, SOFT_AJUSTE_DESCUENTO_GLOBAL, "DESCUENTO GLOBAL DEL CHEQUE", global_discount
            ))
        if courtesy_total > 0:
            out.append(_soft_adjustment_row(
                template, SOFT_AJUSTE_CORTESIA, "CORTESIA / AJUSTE DEL CHEQUE", courtesy_total
            ))

    return out


